-- Per entity, the incident rows a fact-time join reads minus the rows a point-in-time join reads: the raw material of the fabricated AUC.
-- spark dialect. Generated by tools/emit_sql.py; `make sql` regenerates.
SELECT
    p.entity_id,
    SUM(CASE WHEN e.fact_time <= p.prediction_time
             THEN 1 ELSE 0 END) AS rows_fact_only,
    SUM(CASE WHEN e.fact_time <= p.prediction_time
              AND e.arrival_time <= p.prediction_time
             THEN 1 ELSE 0 END) AS rows_point_in_time,
    SUM(CASE WHEN e.fact_time <= p.prediction_time
              AND e.arrival_time > p.prediction_time
             THEN 1 ELSE 0 END) AS rows_unknowable
FROM predictions AS p
JOIN events AS e
  ON e.entity_id = p.entity_id
 AND e.fact_time > p.prediction_time - INTERVAL 90 DAY
 AND e.event_type = 'incident'
GROUP BY p.entity_id
ORDER BY rows_unknowable DESC, p.entity_id
